const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');
const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');
const finalScoreEl = document.getElementById('final-score');

// Game States
const STATE_START = 0;
const STATE_PLAYING = 1;
const STATE_GAMEOVER = 2;
let gameState = STATE_START;

let score = 0;
let highScore = localStorage.getItem('neonRunnerHighScore') || 0;
highScoreEl.textContent = highScore;

let gameSpeed = 6;
let gravity = 0.6;

// Player object
const player = {
    x: 80,
    y: 300,
    width: 36,
    height: 48,
    vy: 0,
    jumpPower: -11.5,
    isGrounded: true,
    isDucking: false,
    normalHeight: 48,
    duckHeight: 26,
    color: '#00f0ff'
};

// Obstacles and Particles
let obstacles = [];
let particles = [];
let stars = [];

// Initialize background stars
for (let i = 0; i < 50; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (canvas.height - 80),
        size: Math.random() * 2 + 1,
        speed: Math.random() * 0.5 + 0.2
    });
}

// Input handling
const keys = {};
window.addEventListener('keydown', e => {
    if (['Space', 'ArrowUp', 'ArrowDown'].includes(e.code)) {
        e.preventDefault(); // Prevent page scrolling
    }
    keys[e.code] = true;

    if ((e.code === 'Space' || e.code === 'ArrowUp') && gameState === STATE_START) {
        startGame();
    }
    if ((e.code === 'Space' || e.code === 'ArrowUp') && gameState === STATE_GAMEOVER) {
        resetGame();
    }
});

window.addEventListener('keyup', e => {
    keys[e.code] = false;
});

startBtn.addEventListener('click', startGame);
restartBtn.addEventListener('click', resetGame);

function startGame() {
    gameState = STATE_PLAYING;
    startScreen.classList.add('hidden');
    score = 0;
    gameSpeed = 6;
    obstacles = [];
    particles = [];
}

function resetGame() {
    gameState = STATE_PLAYING;
    gameOverScreen.classList.add('hidden');
    score = 0;
    gameSpeed = 6;
    obstacles = [];
    particles = [];
    player.y = 300;
    player.vy = 0;
}

// Spawner timers
let obstacleTimer = 0;
let nextObstacleInterval = 100;

function spawnObstacle() {
    const typeRand = Math.random();

    if (typeRand < 0.5) {
        // Ground spike
        obstacles.push({
            x: canvas.width,
            y: 348,
            width: 28,
            height: 36,
            type: 'spike',
            color: '#ff007f'
        });
    } else if (typeRand < 0.8) {
        // High flying drone / laser bar (requires ducking or precise jump)
        obstacles.push({
            x: canvas.width,
            y: 260,
            width: 45,
            height: 18,
            type: 'drone',
            color: '#ffe600'
        });
    } else {
        // Double spike
        obstacles.push({
            x: canvas.width,
            y: 348,
            width: 60,
            height: 36,
            type: 'double',
            color: '#ff007f'
        });
    }
}

// Update game logic
function update() {
    if (gameState !== STATE_PLAYING) return;

    // Score & Speed scaling
    score += 0.1;
    scoreEl.textContent = Math.floor(score);
    gameSpeed = 6 + Math.floor(score / 150) * 0.7;

    // Ducking input
    if (keys['ArrowDown']) {
        if (!player.isDucking && player.isGrounded) {
            player.isDucking = true;
            player.height = player.duckHeight;
            player.y += (player.normalHeight - player.duckHeight);
        }
    } else {
        if (player.isDucking) {
            player.isDucking = false;
            player.y -= (player.normalHeight - player.duckHeight);
            player.height = player.normalHeight;
        }
    }

    // Jumping input
    if ((keys['Space'] || keys['ArrowUp']) && player.isGrounded && !player.isDucking) {
        player.vy = player.jumpPower;
        player.isGrounded = false;
        // Spawn jump particles
        for (let i = 0; i < 8; i++) {
            particles.push({
                x: player.x + player.width / 2,
                y: player.y + player.height,
                vx: (Math.random() - 0.5) * 4,
                size: Math.random() * 3 + 1,
                life: 20,
                color: '#00f0ff'
            });
        }
    }

    // Apply gravity
    player.vy += gravity;
    player.y += player.vy;

    // Ground collision
    const groundLevel = 348;
    if (player.y + player.height >= groundLevel) {
        player.y = groundLevel - player.height;
        player.vy = 0;
        player.isGrounded = true;
    }

    // Update stars
    stars.forEach(star => {
        star.x -= star.speed + (gameSpeed * 0.1);
        if (star.x < 0) star.x = canvas.width;
    });

    // Obstacle spawning
    obstacleTimer++;
    if (obstacleTimer >= nextObstacleInterval) {
        spawnObstacle();
        obstacleTimer = 0;
        // Randomize next interval based on speed
        nextObstacleInterval = Math.floor(Math.random() * 40 + 70) - Math.min(30, Math.floor(gameSpeed * 2));
    }

    // Update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
        let obs = obstacles[i];
        obs.x -= gameSpeed;

        // Collision detection (AABB)
        // Add a slight padding for forgiving hitboxes
        const padding = 6;
        if (
            player.x + padding < obs.x + obs.width - padding &&
            player.x + player.width - padding > obs.x + padding &&
            player.y + padding < obs.y + obs.height - padding &&
            player.y + player.height - padding > obs.y + padding
        ) {
            // Game Over!
            gameState = STATE_GAMEOVER;
            finalScoreEl.textContent = Math.floor(score);
            if (Math.floor(score) > highScore) {
                highScore = Math.floor(score);
                localStorage.setItem('neonRunnerHighScore', highScore);
                highScoreEl.textContent = highScore;
            }
            gameOverScreen.classList.remove('hidden');
        }

        // Remove offscreen obstacles
        if (obs.x + obs.width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.life--;
        if (p.life <= 0) {
            particles.splice(i, 1);
        }
    }
}

// Render graphics
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background stars
    ctx.fillStyle = '#ffffff';
    stars.forEach(star => {
        ctx.globalAlpha = star.size / 3;
        ctx.fillRect(star.x, star.y, star.size, star.size);
    });
    ctx.globalAlpha = 1.0;

    // Draw grid lines on ground / background for retro neon synthwave effect
    ctx.strokeStyle = 'rgba(0, 240, 255, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x < canvas.width; x += 40) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, 348);
        ctx.stroke();
    }

    // Draw ground line
    ctx.strokeStyle = '#ff007f';
    ctx.lineWidth = 3;
    ctx.shadowColor = '#ff007f';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.moveTo(0, 348);
    ctx.lineTo(canvas.width, 348);
    ctx.stroke();
    ctx.shadowBlur = 0; // reset shadow

    // Draw obstacles
    obstacles.forEach(obs => {
        ctx.fillStyle = obs.color;
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 12;

        if (obs.type === 'spike') {
            ctx.beginPath();
            ctx.moveTo(obs.x, obs.y + obs.height);
            ctx.lineTo(obs.x + obs.width / 2, obs.y);
            ctx.lineTo(obs.x + obs.width, obs.y + obs.height);
            ctx.closePath();
            ctx.fill();
        } else if (obs.type === 'double') {
            ctx.beginPath();
            // Spike 1
            ctx.moveTo(obs.x, obs.y + obs.height);
            ctx.lineTo(obs.x + 14, obs.y);
            ctx.lineTo(obs.x + 28, obs.y + obs.height);
            // Spike 2
            ctx.moveTo(obs.x + 32, obs.y + obs.height);
            ctx.lineTo(obs.x + 46, obs.y);
            ctx.lineTo(obs.x + 60, obs.y + obs.height);
            ctx.closePath();
            ctx.fill();
        } else if (obs.type === 'drone') {
            // Glowing hover drone
            ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
            // Laser core
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(obs.x + 5, obs.y + 6, obs.width - 10, 6);
        }
        ctx.shadowBlur = 0;
    });

    // Draw particles
    particles.forEach(p => {
        ctx.fillStyle = p.color;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 6;
        ctx.fillRect(p.x, p.y, p.size, p.size);
        ctx.shadowBlur = 0;
    });

    // Draw player
    ctx.fillStyle = player.color;
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 15;

    // Player body
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Player visor / neon eye
    ctx.fillStyle = '#ffffff';
    if (!player.isDucking) {
        ctx.fillRect(player.x + 20, player.y + 10, 12, 6);
    } else {
        ctx.fillRect(player.x + 20, player.y + 6, 10, 4);
    }

    ctx.shadowBlur = 0;
}

// Main game loop
function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
}

// Start loop
loop();

