const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over');
const startBtn = document.getElementById('start-btn');
const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');

let gameState = 'START'; // START, PLAYING, GAMEOVER
let score = 0;
let highScore = localStorage.getItem('neonJumperHighScore') || 0;
highScoreEl.textContent = highScore;

// Game variables
const gravity = 0.6;
let gameSpeed = 5;

const player = {
    x: 80,
    y: 280,
    width: 35,
    height: 45,
    dy: 0,
    jumpForce: -11,
    grounded: false,
    jumpsLeft: 2,
    maxJumps: 2,
    rotation: 0
};

let obstacles = [];
let particles = [];
let stars = [];

// Initialize background stars
for (let i = 0; i < 50; i++) {
    stars.push({
        x: Math.random() * canvas.width,
        y: Math.random() * (canvas.height - 80),
        size: Math.random() * 2 + 1,
        speed: Math.random() * 0.5 + 0.2
    });
}

function createParticle(x, y, color) {
    for (let i = 0; i < 8; i++) {
        particles.push({
            x: x,
            y: y,
            dx: (Math.random() - 0.5) * 6,
            dy: (Math.random() - 0.5) * 6,
            size: Math.random() * 4 + 2,
            color: color,
            life: 30
        });
    }
}

function spawnObstacle() {
    const types = ['spike', 'tall', 'floating'];
    const type = types[Math.floor(Math.random() * types.length)];

    let obs = {
        x: canvas.width,
        width: 30,
        height: 40,
        y: 305,
        color: '#ff0055'
    };

    if (type === 'tall') {
        obs.height = 65;
        obs.y = 280;
        obs.color = '#ff5500';
    } else if (type === 'floating') {
        obs.width = 40;
        obs.height = 25;
        obs.y = 210;
        obs.color = '#bf00ff';
    } else {
        obs.width = 30;
        obs.height = 40;
        obs.y = 305;
        obs.color = '#ff0055';
    }

    obstacles.push(obs);
}

let spawnTimer = 0;
let spawnInterval = 90;

function resetGame() {
    score = 0;
    scoreEl.textContent = score;
    gameSpeed = 5;
    spawnTimer = 0;
    spawnInterval = 90;
    obstacles = [];
    particles = [];
    player.y = 280;
    player.dy = 0;
    player.jumpsLeft = 2;
    player.rotation = 0;
    gameState = 'PLAYING';
    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
}

function jump() {
    if (gameState === 'START') {
        resetGame();
        return;
    }
    if (gameState === 'GAMEOVER') {
        resetGame();
        return;
    }

    if (player.jumpsLeft > 0) {
        player.dy = player.jumpForce;
        player.grounded = false;
        player.jumpsLeft--;
        createParticle(player.x + player.width / 2, player.y + player.height, player.jumpsLeft === 0 ? '#ff0055' : '#00f3ff');
    }
}

// Controls
window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'ArrowUp') {
        e.preventDefault();
        jump();
    }
});

canvas.addEventListener('click', () => {
    jump();
});

startBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    resetGame();
});

function update() {
    if (gameState !== 'PLAYING') return;

    // Score & Speed
    score++;
    if (score % 100 === 0) {
        gameSpeed += 0.5;
        if (spawnInterval > 45) spawnInterval -= 5;
    }
    scoreEl.textContent = Math.floor(score / 10);

    // Player physics
    player.dy += gravity;
    player.y += player.dy;

    // Ground collision
    const groundLevel = 345 - player.height;
    if (player.y > groundLevel) {
        player.y = groundLevel;
        player.dy = 0;
        player.grounded = true;
        player.jumpsLeft = player.maxJumps;
        player.rotation = 0;
    } else {
        player.rotation += 0.15;
    }

    // Stars update
    stars.forEach(star => {
        star.x -= star.speed;
        if (star.x < 0) star.x = canvas.width;
    });

    // Obstacles spawn
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
        spawnObstacle();
        spawnTimer = 0;
        spawnInterval = Math.floor(Math.random() * 40) + 70 - Math.min(score / 50, 20);
    }

    // Obstacles update & collision
    for (let i = obstacles.length - 1; i >= 0; i--) {
        obstacles[i].x -= gameSpeed;

        // AABB Collision with slight padding for fairness
        const padding = 6;
        if (
            player.x + padding < obstacles[i].x + obstacles[i].width - padding &&
            player.x + player.width - padding > obstacles[i].x + padding &&
            player.y + padding < obstacles[i].y + obstacles[i].height - padding &&
            player.y + player.height - padding > obstacles[i].y + padding
        ) {
            gameState = 'GAMEOVER';
            gameOverScreen.classList.remove('hidden');
            createParticle(player.x + player.width/2, player.y + player.height/2, '#ff0055');

            const currentScoreVal = Math.floor(score / 10);
            if (currentScoreVal > highScore) {
                highScore = currentScoreVal;
                highScoreEl.textContent = highScore;
                localStorage.setItem('neonJumperHighScore', highScore);
            }
        }

        // Remove offscreen
        if (obstacles[i].x + obstacles[i].width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Particles update
    for (let i = particles.length - 1; i >= 0; i--) {
        particles[i].x += particles[i].dx;
        particles[i].y += particles[i].dy;
        particles[i].life--;
        if (particles[i].life <= 0) {
            particles.splice(i, 1);
        }
    }
}

function draw() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw background stars
    ctx.fillStyle = '#ffffff';
    stars.forEach(star => {
